

# This file was *autogenerated* from the file /workspace/leanproject/Submission/get_optimal_residues.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_40 = Integer(40); _sage_const_10 = Integer(10); _sage_const_16 = Integer(16); _sage_const_4 = Integer(4); _sage_const_9 = Integer(9); _sage_const_160 = Integer(160); _sage_const_3 = Integer(3); _sage_const_11 = Integer(11); _sage_const_31 = Integer(31); _sage_const_43 = Integer(43); _sage_const_127 = Integer(127); _sage_const_23 = Integer(23); _sage_const_19 = Integer(19); _sage_const_59 = Integer(59); _sage_const_71 = Integer(71); _sage_const_83 = Integer(83); _sage_const_47 = Integer(47); _sage_const_67 = Integer(67); _sage_const_103 = Integer(103); _sage_const_22 = Integer(22); _sage_const_0 = Integer(0); _sage_const_2 = Integer(2)
def precompute_V():
    V = {_sage_const_1 }
    for s in range(_sage_const_40 ):
        fs = (_sage_const_10  * _sage_const_16 **s + _sage_const_16  * _sage_const_4 **s + _sage_const_10 ) // _sage_const_9 
        for i in range(_sage_const_160 ):
            val = fs * _sage_const_4 **i
            V.add(val)
    return sorted(list(V))

all_V = precompute_V()

# 13 base primes
selected_primes = [_sage_const_3 , _sage_const_11 , _sage_const_31 , _sage_const_43 , _sage_const_127 , _sage_const_23 , _sage_const_19 , _sage_const_59 , _sage_const_71 , _sage_const_83 , _sage_const_47 , _sage_const_67 , _sage_const_103 ]

N_max = _sage_const_10 **_sage_const_22 
limit = N_max * N_max
V_target = [v for v in all_V if v < limit]

selected_residues = {}
uncovered = list(V_target)

for p in selected_primes:
    cov_for_r = [_sage_const_0 ] * p
    for v in uncovered:
        v_mod = v % p
        if v_mod == _sage_const_0 :
            cov_for_r[_sage_const_0 ] += _sage_const_1 
        elif pow(v_mod, (p-_sage_const_1 )//_sage_const_2 , p) == _sage_const_1 :
            for r in range(_sage_const_1 , p):
                if (r*r) % p == v_mod:
                    cov_for_r[r] += _sage_const_1 
                    cov_for_r[p-r] += _sage_const_1 
                    break
    max_cov = max(cov_for_r)
    best_r = cov_for_r.index(max_cov)
    selected_residues[p] = best_r
    
    # Remove covered
    new_uncovered = []
    r2 = (best_r * best_r) % p
    for v in uncovered:
        if v % p != r2:
            new_uncovered.append(v)
    uncovered = new_uncovered

moduli = [_sage_const_2 ] + selected_primes
residues = [_sage_const_1 ] + [selected_residues[p] for p in selected_primes]
from math import prod as math_prod
base_prod = math_prod(moduli)
N0 = int(crt(residues, moduli))

print(f"N0 = {N0}")
print(f"prod = {base_prod}")
print(f"uncovered remaining = {len(uncovered)}")

